use crate::store::{Store,Result,text,uid,now};
use serde_json::{Value,json};
use std::sync::{Arc,Mutex};
#[derive(Clone)]
pub struct VoiceStudio {pub store:Store,pub secrets:Arc<Mutex<Value>>}
impl VoiceStudio {
 fn key(&self)->Result<String>{let k=text(&self.secrets.lock().unwrap(),"voicestudioKey");if k.is_empty(){Err("Add the VoiceStudio API key in Settings".into())}else{Ok(k)}}
 async fn request(&self,path:&str,body:Option<(Vec<u8>,String)>)->Result<reqwest::Response>{let c=reqwest::Client::builder().redirect(reqwest::redirect::Policy::none()).timeout(std::time::Duration::from_secs(600)).build().map_err(|e|e.to_string())?;let url=format!("https://gx10-54fa.tail5903e7.ts.net:9444{path}");let r=if let Some((b,t))=body{c.post(url).header("Content-Type",t).body(b)}else{c.get(url)}.bearer_auth(self.key()?).send().await.map_err(|_|"Could not reach VoiceStudio on GX10")?;if !r.status().is_success(){return Err(format!("VoiceStudio returned {}. Check the service and API key.",r.status()));}Ok(r)}
 pub async fn check(&self)->Result<Value>{self.request("/health",None).await?;Ok(json!({"ok":true}))}
 pub fn claim(&self,id:&str)->Result<Value>{self.key()?;self.store.update(|s|{let j=s["jobs"].as_array_mut().unwrap().iter_mut().find(|j|j["id"]==id).ok_or("Take not found")?;if j["status"]!="prepared"||j["kind"]!="voice"{return Err("Save a new speech take first".into());}j["status"]=json!("submitting");j["error"]=json!("");Ok(json!({"ok":true}))})}
 pub async fn run(&self,id:&str){if let Err(e)=self.speech(id).await{let _=self.store.update(|s|{if let Some(j)=s["jobs"].as_array_mut().unwrap().iter_mut().find(|j|j["id"]==id){j["status"]=json!("failed");j["error"]=json!(e);}Ok(())});}}
 async fn speech(&self,id:&str)->Result<()>{let s=self.store.read();let j=s["jobs"].as_array().unwrap().iter().find(|j|j["id"]==id).ok_or("Take not found")?;let a=self.store.asset(&text(&j["inputs"],"voice"))?;let bytes=std::fs::read(self.store.asset_path(&a)?).map_err(|e|e.to_string())?;if bytes.len()>20*1024*1024{return Err("Use a voice recording smaller than 20 MB".into());}let boundary=format!("mytwin{}",uid());let mut body=Vec::new();for (k,v) in [("text",text(j,"text")),("language",text(j,"language")),("num_step","32".into()),("wav_bits","16".into()),("engine","omnivoice".into()),("ref_text",text(j,"referenceText"))]{body.extend(format!("--{boundary}\r\nContent-Disposition: form-data; name=\"{k}\"\r\n\r\n{v}\r\n").as_bytes());}body.extend(format!("--{boundary}\r\nContent-Disposition: form-data; name=\"ref_audio\"; filename=\"reference.wav\"\r\nContent-Type: application/octet-stream\r\n\r\n").as_bytes());body.extend(bytes);body.extend(format!("\r\n--{boundary}--\r\n").as_bytes());let mut r=self.request("/generate",Some((body,format!("multipart/form-data; boundary={boundary}")))).await?;let mut audio=Vec::new();while let Some(c)=r.chunk().await.map_err(|_|"Speech download interrupted")?{if audio.len()+c.len()>128*1024*1024{return Err("Audio exceeds 128 MB".into());}audio.extend(c);}if audio.get(..4)!=Some(b"RIFF")||audio.get(8..12)!=Some(b"WAVE"){return Err("VoiceStudio returned invalid WAV audio".into());}let aid=uid();std::fs::write(self.store.dir.join("media").join(&aid),&audio).map_err(|e|e.to_string())?;self.store.update(|s|{s["assets"].as_array_mut().unwrap().push(json!({"id":aid,"name":format!("{}.wav",text(j,"sectionTitle")),"type":"audio/wav","size":audio.len(),"createdAt":now()}));let take=s["jobs"].as_array_mut().unwrap().iter_mut().find(|j|j["id"]==id).ok_or("Take not found")?;take["status"]=json!("completed");take["outputId"]=json!(aid);take["updatedAt"]=json!(now());Ok(())})}
}
